protected boolean closure(@NotNull CharStream input, @NotNull LexerATNConfig config, @NotNull ATNConfigSet configs, boolean currentAltReachedAcceptState, boolean speculative) {
    logDebugInfo(config);

    if (isRuleStopState(config)) {
        currentAltReachedAcceptState = handleRuleStopState(input, config, configs, currentAltReachedAcceptState);
        return currentAltReachedAcceptState;
    }

    optimizeConfigs(configs, config, currentAltReachedAcceptState);
    return processTransitions(input, config, configs, currentAltReachedAcceptState, speculative);
}

private void logDebugInfo(LexerATNConfig config) {
    if (debug) {
        System.out.println("closure(" + config.toString(recog, true) + ")");
    }
}

private boolean isRuleStopState(LexerATNConfig config) {
    return config.state instanceof RuleStopState;
}

private boolean handleRuleStopState(CharStream input, LexerATNConfig config, ATNConfigSet configs, boolean currentAltReachedAcceptState) {
    logRuleStopState(config);

    if (config.context == null || config.context.hasEmptyPath()) {
        if (config.context == null || config.context.isEmpty()) {
            configs.add(config);
            return true;
        } else {
            configs.add(new LexerATNConfig(config, config.state, PredictionContext.EMPTY));
            currentAltReachedAcceptState = true;
        }
    }

    if (config.context != null && !config.context.isEmpty()) {
        currentAltReachedAcceptState = processContexts(input, config, configs, currentAltReachedAcceptState);
    }

    return currentAltReachedAcceptState;
}

private void logRuleStopState(LexerATNConfig config) {
    if (debug) {
        if (recog != null) {
            System.out.format("closure at %s rule stop %s\
", recog.getRuleNames()[config.state.ruleIndex], config);
        } else {
            System.out.format("closure at rule stop %s\
", config);
        }
    }
}

private boolean processContexts(CharStream input, LexerATNConfig config, ATNConfigSet configs, boolean currentAltReachedAcceptState) {
    for (SingletonPredictionContext ctx : config.context) {
        if (!ctx.isEmpty()) {
            PredictionContext newContext = ctx.parent;
            if (ctx.returnState == PredictionContext.EMPTY_RETURN_STATE) {
                recordFallbackToken(config, ctx, configs);
                continue;
            }
            ATNState returnState = atn.states.get(ctx.returnState);
            LexerATNConfig newConfig = new LexerATNConfig(returnState, config.alt, newContext);
            currentAltReachedAcceptState = closure(input, newConfig, configs, currentAltReachedAcceptState, speculative);
        }
    }
    return currentAltReachedAcceptState;
}

private void recordFallbackToken(LexerATNConfig config, SingletonPredictionContext ctx, ATNConfigSet configs) {
    LexerATNConfig c = new LexerATNConfig(config, config.state, ctx);
    if (debug) {
        System.out.println("FALLING off token " + recog.getRuleNames()[config.state.ruleIndex] + " record " + c);
    }
    configs.add(c);
}

private void optimizeConfigs(ATNConfigSet configs, LexerATNConfig config, boolean currentAltReachedAcceptState) {
    if (!config.state.onlyHasEpsilonTransitions()) {
        if (!currentAltReachedAcceptState || !config.hasPassedThroughNonGreedyDecision()) {
            configs.add(config);
        }
    }
}

private boolean processTransitions(CharStream input, LexerATNConfig config, ATNConfigSet configs, boolean currentAltReachedAcceptState, boolean speculative) {
    ATNState p = config.state;
    for (int i = 0; i < p.getNumberOfTransitions(); i++) {
        Transition t = p.transition(i);
        LexerATNConfig c = getEpsilonTarget(input, config, t, configs, speculative);
        if (c != null) {
            currentAltReachedAcceptState = closure(input, c, configs, currentAltReachedAcceptState, speculative);
        }
    }
    return currentAltReachedAcceptState;
}

