protected boolean closure(@NotNull CharStream input, @NotNull LexerATNConfig config, 
                          @NotNull ATNConfigSet configs, boolean currentAltReachedAcceptState, 
                          boolean speculative) {
    logDebugClosure(config);

    if (isRuleStopState(config.state)) {
        logDebugRuleStop(config);
        return handleRuleStopState(input, config, configs, currentAltReachedAcceptState, speculative);
    }

    if (!config.state.onlyHasEpsilonTransitions()) {
        handleNonEpsilonTransition(config, currentAltReachedAcceptState, configs);
    }

    return processTransitions(input, config, configs, currentAltReachedAcceptState, speculative);
