private boolean handleRuleStopState(CharStream input, LexerATNConfig config, 
                                     ATNConfigSet configs, boolean currentAltReachedAcceptState, 
                                     boolean speculative) {
    if (config.context == null || config.context.hasEmptyPath()) {
        if (config.context == null || config.context.isEmpty()) {
            configs.add(config);
            return true;
        } else {
            configs.add(new LexerATNConfig(config, config.state, PredictionContext.EMPTY));
